+                isOn={isJsonView}
+                onChange={onToggleJsonView}
+              />
+            )}
+          </div>
+        </div>
+
+        {!entities.length ? (
+          <DialNoDataContent title={t(QueryBuilderI18nKey.EntitiesLoadFailed)} />
+        ) : isJsonView && fieldsLoaded ? (
+          <div className="flex flex-1 min-h-0 flex-col gap-2">
