+            {fieldsLoaded && (
+              <CopyButton
+                value={isJsonView ? jsonText : json}
+                valueLabel={t(QueryBuilderI18nKey.StructuredQueryJson)}
+                buttonLabel={t(ButtonsI18nKey.Copy)}
