+            <DialPrimaryButton
+              label={t(QueryBuilderI18nKey.Run)}
+              iconBefore={<IconPlayerPlay {...BASE_BUTTON_ICON_PROPS} />}
+              disabled={!fieldsLoaded || (isJsonView && jsonInvalid)}
